export interface WorkerOptions {
  concurrency?: number;
  retries?: number;
}

type Job = () => Promise<void>;

export function createWorker({ concurrency = 2, retries = 1 }: WorkerOptions = {}) {
  const queue: { job: Job; left: number }[] = [];
  let running = 0;

  const pump = (): void => {
    while (running < concurrency && queue.length > 0) {
      const item = queue.shift()!;
      running++;
      item
        .job()
        .catch(() => {
          if (item.left > 0) queue.push({ job: item.job, left: item.left - 1 });
        })
        .finally(() => {
          running--;
          pump();
        });
    }
  };

  return {
    add(job: Job): void {
      queue.push({ job, left: retries });
      pump();
    },
  };
}

